                + '<th>' + esc(t('pages.creds.thSvcUser')) + '</th><th>' + esc(t('pages.creds.thSvcLabel')) + '</th>'
                + '<th>' + esc(t('pages.creds.thSvcHasPwd')) + '</th><th>' + esc(t('pages.creds.thSvcLastAccess')) + '</th>'
